 14	/**
 15	 * Parses an icons JSON file and returns a sorted, filtered list of
 16	 * {@see IconDefinition} instances for use by the language renderers
 17	 * during icon code generation.
 18	 *
 19	 * IDs are normalised on load (hyphens and spaces become underscores).
 20	 * The spinner icon is excluded from the result set because it has
 21	 * special runtime behaviour and must not be overwritten by the builder.
 22	 *
 23	 * @package Application
 24	 * @subpackage Composer
 25	 * @see IconDefinition
 26	 * @see IconBuilder
 27	 */
 28	class IconsReader
 29	{
 30	    public const string EXCLUDED_ICON_SPINNER = 'spinner';
 31	
 32	    private string $jsonPath;
 33	
 34	    /**
 35	     * @var IconDefinition[]|null
 36	     */
 37	    private ?array $icons = null;
 38	
 39	    public function __construct(string $jsonPath)
 40	    {
 41	        $this->jsonPath = $jsonPath;
 42	    }
 43	
 44	    /**
 45	     * Returns the path to the icons JSON file.
 46	     *
 47	     * @return string
 48	     */
 49	    public function getPath() : string
 50	    {
 51	        return $this->jsonPath;
 52	    }
 53	
 54	    /**
 55	     * Returns all parsed icon definitions, sorted alphabetically by ID
 56	     * and with the spinner icon excluded.
 57	     *
 58	     * @return IconDefinition[]
 59	     */
 60	    public function getIcons() : array
 61	    {
 62	        if($this->icons === null)
 63	        {
 64	            $this->icons = $this->load();
 65	        }
 66	
 67	        return $this->icons;
 68	    }
 69	
 70	    /**
 71	     * Returns the number of icon definitions in the parsed set.
 72	     *
 73	     * @return int
 74	     */
 75	    public function countIcons() : int
 76	    {
 77	        return count($this->getIcons());
 78	    }
 79	
 80	    /**
 81	     * Loads and parses the JSON file, normalises IDs, excludes the spinner,
 82	     * and sorts the resulting definitions alphabetically by ID.
 83	     *
 84	     * @return IconDefinition[]
 85	     */
 86	    private function load() : array
 87	    {
 88	        $file = JSONFile::factory($this->jsonPath);
 89	
 90	        $rawData = array();
 91	
 92	        if($file->exists())
 93	        {
 94	            $rawData = $file->parse();
 95	        }
 96	
 97	        $icons = array();
 98	
 99	        foreach($rawData as $rawID => $iconDef)
100	        {

101	            $id = IconInfo::normaliseID((string)$rawID);
102	
103	            if($id === self::EXCLUDED_ICON_SPINNER)
104	            {
105	                continue;
106	            }
107	
108	            $iconName = isset($iconDef['icon']) ? (string)$iconDef['icon'] : '';
109	            $iconType = isset($iconDef['type']) ? (string)$iconDef['type'] : '';
110	
111	            $icons[$id] = new IconDefinition($id, $iconName, $iconType);
112	        }
113	
114	        ksort($icons);
115	
116	        return array_values($icons);
117	    }
